<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>EMRAIS Engineering Services</title>
    <style>
        :root {
            --primary-red: #7a1f1f;
            --primary-dark: #4a0e0e;
            --accent-gold: #d4a017;
            --accent-gold-light: #f0c14b;
            --text-white: #ffffff;
            --text-gray: #e0e0e0;
            --font-main: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--primary-red);
            background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary-red) 50%, #a33232 100%);
            color: var(--text-white);
            min-height: 100vh;
            overflow-x: hidden;
            position: relative;
        }

        /* Navigation */
        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 5%;
            max-width: 1400px;
            margin: 0 auto;
        }

        .logo-area {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .logo-icon {
            width: 44px;
            height: 44px;
            background: white;
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            color: var(--primary-red);
            font-weight: bold;
            font-size: 10px;
            border: 2px solid rgba(255,255,255,0.3);
            position: relative;
            overflow: hidden;
        }

        /* Simulating the logo graphic with CSS */
        .logo-graphic {
            width: 100%;
            height: 100%;
            background: conic-gradient(from 0deg, transparent 0%, var(--primary-red) 100%);
            opacity: 0.1;
            position: absolute;
            top:0; left:0;
        }
        .logo-text-group {
            display: flex;
            flex-direction: column;
            line-height: 1.1;
        }
        .brand-name { font-weight: 800; font-size: 18px; letter-spacing: 0.5px; }
        .brand-sub { font-size: 11px; opacity: 0.8; font-weight: 400; }

        .nav-links {
            display: flex;
            gap: 24px;
            list-style: none;
            font-size: 14px;
            font-weight: 500;
        }
        .nav-links a {
            text-decoration: none;
            color: white;
            transition: opacity 0.2s;
        }
        .nav-links a:hover { opacity: 0.8; }

        .cta-btn {
            background-color: #c0392b;
            color: white;
            padding: 10px 20px;
            border-radius: 6px;
            text-decoration: none;
            font-size: 13px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 8px;
            transition: transform 0.2s;
        }
        .cta-btn:hover { transform: translateY(-1px); }

        /* Hero Section */
        .hero-container {
            max-width: 1300px;
            margin: 60px auto 80px;
            padding: 0 5%;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
            align-items: center;
            min-height: 70vh;
        }

        /* Left Content */
        .hero-content {
            z-index: 2;
        }

        .badge-small {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: rgba(212, 160, 23, 0.15);
            border: 1px solid rgba(212, 160, 23, 0.4);
            color: var(--accent-gold-light);
            padding: 6px 12px;
            border-radius: 20px;
            font-size: 11px;
            font-weight: 700;
            margin-bottom: 24px;
            letter-spacing: 0.5px;
        }

        h1 {
            font-size: 56px;
            line-height: 1.05;
            font-weight: 800;
            margin-bottom: 28px;
            letter-spacing: -1px;
        }
        h1 span { color: var(--accent-gold); }

        p.hero-desc {
            font-size: 16px;
            line-height: 1.6;
            margin-bottom: 36px;
            max-width: 90%;
            color: rgba(255,255,255,0.9);
            font-weight: 300;
        }

        .action-buttons {
            display: flex;
            gap: 16px;
        }

        .btn-primary {
            background-color: var(--accent-gold);
            color: #3e2a00;
            padding: 14px 28px;
            border-radius: 6px;
            text-decoration: none;
            font-weight: 700;
            font-size: 14px;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.2);
            transition: all 0.2s;
        }
        .btn-primary:hover { filter: brightness(1.1); transform: translateY(-2px); }

        .btn-secondary {
            background: transparent;
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            padding: 14px 28px;
            border-radius: 6px;
            text-decoration: none;
            font-weight: 500;
            font-size: 14px;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            transition: all 0.2s;
        }
        .btn-secondary:hover { background: rgba(255,255,255,0.1); border-color: white; }


        /* Right Content - Stacked Cards */
        .visual-stack {
            position: relative;
            height: 500px;
            display: flex;
            justify-content: center;
            align-items: center;
            perspective: 1000px;
        }

        .card-wrapper {
            position: relative;
            width: 420px;
            height: 480px;
            transform-style: preserve-3d;
        }

        /* The Stack Effect (Background Cards) */
        .stack-card {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border-radius: 20px;
            overflow: hidden;
            box-shadow: -10px 10px 30px rgba(0,0,0,0.4);
            transition: transform 0.4s ease, box-shadow 0.4s ease;
            background: #333;
        }

        /* Card 3 (Bottom) */
        .stack-card:nth-child(1) {
            background: url('https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=800&q=80') center/cover no-repeat;
            transform: translate(-25px, 25px) scale(0.95);
            z-index: 1;
            opacity: 0.6;
        }

        /* Card 2 (Middle) */
        .stack-card:nth-child(2) {
            background: url('https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=800&q=80') center/cover no-repeat;
            transform: translate(-12px, 12px) scale(0.975);
            z-index: 2;
            opacity: 0.8;
        }

        /* Card 1 (Top / Active) */
        .stack-card:nth-child(3) {
            background: url('https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=800&q=80') center/cover no-repeat;
            z-index: 3;
            cursor: pointer;
            border: 4px solid rgba(255,255,255,0.1); /* Subtle edge highlight */
        }

        /* Hover Interaction for the Stack */
        .visual-stack:hover .stack-card:nth-child(1) {
            transform: translate(-35px, 35px) scale(0.95);
        }
        .visual-stack:hover .stack-card:nth-child(2) {
            transform: translate(-18px, 18px) scale(0.975);
        }
        .visual-stack:hover .stack-card:nth-child(3) {
            transform: translate(-5px, -5px) scale(1.02);
            box-shadow: -15px 15px 40px rgba(0,0,0,0.5);
        }

        /* Overlay Content on Top Card */
        .card-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 24px;
            background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
            color: white;
            z-index: 10;
            pointer-events: none; /* Let clicks pass through if needed, though we want hover on parent */
        }

        .status-badge {
            display: inline-block;
            background: var(--accent-gold);
            color: #3e2a00;
            font-size: 10px;
            font-weight: 800;
            padding: 4px 10px;
            border-radius: 4px;
            margin-bottom: 10px;
            text-transform: uppercase;
        }

        .project-title {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 4px;
        }

        .project-location {
            font-size: 13px;
            opacity: 0.8;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* Gold Corner Badge */
        .corner-badge {
            position: absolute;
            top: 20px;
            right: -10px;
            background: var(--accent-gold);
            color: #fff;
            padding: 8px 16px 8px 12px;
            font-size: 10px;
            font-weight: 800;
            text-transform: uppercase;
            border-bottom-left-radius: 20px;
            border-top-left-radius: 20px;
            box-shadow: 0 4px 10px rgba(0,0,0,0.3);
            z-index: 20;
            transform: rotate(0deg);
            display: flex;
            flex-direction: column;
            align-items: center;
            line-height: 1;
        }
        .corner-badge::after {
            content: "★";
            font-size: 10px;
            margin-top: 2px;
            color: #fff;
        }

        /* Hint Text */
        .hover-hint {
            position: absolute;
            bottom: -40px;
            left: 50%;
            transform: translateX(-50%);
            color: rgba(255,255,255,0.6);
            font-size: 12px;
            display: flex;
            align-items: center;
            gap: 10px;
            white-space: nowrap;
            animation: pulse 2s infinite;
        }
        .hint-line {
            width: 30px;
            height: 1px;
            background: rgba(255,255,255,0.4);
        }

        @keyframes pulse {
            0% { opacity: 0.6; }
            50% { opacity: 1; }
            100% { opacity: 0.6; }
        }

        /* Responsive */
        @media (max-width: 1024px) {
            h1 { font-size: 42px; }
            .hero-container { grid-template-columns: 1fr; gap: 60px; }
            .visual-stack { order: -1; } /* Image first on mobile usually, but keeping layout logic simple */
            .card-wrapper { width: 320px; height: 380px; }
        }
    </style>
</head>
