        </ul>

        <a href="#" class="cta-btn">
            Get a Quote 
            <span>→</span>
        </a>
    </nav>

    <!-- Hero Section -->
    <main class="hero-container">
        <!-- Left Text Content -->
        <section class="hero-content">
            <div class="badge-small">
                <span>◎</span> RC No. 1617574 · Incorporated 2019
            </div>

            <h1>
                Engineering <br>
                <span>Excellence,</span> <br>
                Transforming <br>
                Concepts <br>
                Into Reality
            </h1>

            <p class="hero-desc">
                An indigenous Nigerian firm providing premier Engineering Services, General Supplies, and General Contracts. From foundation to finishing, we deliver quality you can trust.
            </p>

            <div class="action-buttons">
                <a href="#" class="btn-primary">
                    Explore Our Services
                    <span>›</span>
                </a>
                <a href="#" class="btn-secondary">
                    Contact Us
                    <span>📞</span>
                </a>
            </div>
        </section>

        <!-- Right Visual Content -->
        <aside class="visual-stack">
            <div class="card-wrapper">

                <!-- Background Card 3 -->
                <div class="stack-card"></div>

                <!-- Background Card 2 -->
                <div class="stack-card"></div>

                <!-- Top Active Card -->
                <div class="stack-card">
                    <!-- Gold Badge -->
                    <div class="corner-badge">
                        Our Work
                    </div>

                    <!-- Card Info Overlay -->
                    <div class="card-overlay">
                        <div class="status-badge">◎ Completed · 2022</div>
                        <div class="project-title">Contemporary Family Duplex</div>
                        <div class="project-location">
                            <span>◎</span> Kaduna State
                        </div>
                    </div>
                </div>

            </div>

            <!-- Hover Instruction -->
            <div class="hover-hint">
                <div class="hint-line"></div>
                <span>Hover to explore our projects</span>
                <div class="hint-line"></div>
            </div>
        </aside>
    </main>

</body>
</html>
```
